  .local-label { display: none; }
  .hero { min-height: 212px; margin-top: 16px; }
  .hero-copy { padding: 28px 15px 28px 20px; }
  .hero h1 { font-size: clamp(2.6rem, 9vw, 4.2rem); }
  .hero-description { font-size: .92rem; max-width: 230px; }
  .hero-break { display: none; }
  .hero-art { left: 59%; opacity: .64; mask-image: linear-gradient(to right, transparent, #000 40%); }
  .fabric { width: 180px; }
  .summary { gap: 7px; margin-top: 12px; }
  .summary-card { padding: 8px; gap: 6px; min-height: 66px; }
  .metric-icon { width: 29px; height: 29px; border-radius: 6px; }
  .metric-icon .icon { width: 16px; height: 16px; }
  .metric-label { font-size: .72rem; }
  .metric-copy strong { font-size: 1.45rem; }
  .inventory { margin-top: 21px; }
  .section-heading h2 { font-size: 1.75rem; }
  .filters { padding: 12px 11px 7px; }
  .filter-row { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
  .search-control { grid-column: 1 / -1; }
  .filter-row select { padding-left: 7px; font-size: .81rem; padding-right: 21px; }
  .select-wrap > .icon { right: 4px; width: 15px; }
  .drawers { gap: 4px; padding-left: 49px; }
  .drawers label span { min-width: 30px; }
  .drawers label:first-of-type span { min-width: 35px; }
  table, tbody { display: block; }
  thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  thead button { visibility: hidden; }
  tbody tr { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 4px 10px; padding: 8px 11px; border-bottom: 1px solid var(--line); }
  tbody tr:first-child { border-top: 1px solid var(--line); }
  tbody td, tbody td:first-child, tbody td:last-child { height: auto; width: auto; border: 0; padding: 0; }
  tbody td:nth-child(1) { grid-area: 1 / 1; }
  tbody td:nth-child(2) { grid-area: 2 / 1; }
  tbody td:nth-child(3) { grid-area: 2 / 2; }
  tbody td:nth-child(4) { grid-area: 2 / 3; justify-self: end; }
  tbody td:nth-child(5) { grid-area: 1 / 2; }
  tbody td:nth-child(6) { grid-area: 1 / 3; }
  .color-cell { gap: 4px; }
  .color-chip { width: 14px; height: 14px; }
  .drawer-chip { width: auto; padding: 0 5px; }
  .drawer-chip::before { content: "Drawer "; display: inline; margin-right: 4px; }
  .drawer-chip { display: inline-flex; align-items: center; }
  .table-footer { padding-inline: 11px; }
}

@media (max-width: 385px) {
  .summary-card { gap: 4px; }
  .metric-icon { width: 23px; height: 26px; }
  .metric-label { font-size: .68rem; }
  .section-heading h2 { font-size: 1.55rem; }
  .drawers label span { min-width: 27px; }
}

